import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
C='SCA'
E(C,'M1-Z1','Scarichi: definizioni e tipologie',[CL("Che tipo di acqua reflua?","Seleziona un refluo, poi la tipologia.",["Domestica o assimilata","Industriale","Meteorica di dilavamento"],[
 ["Servizi igienici degli uffici",0,"Deriva dal metabolismo umano e da attività domestiche."],
 ["Acque di lavaggio dei pezzi metallici in una linea di sgrassaggio",1,"Deriva da un’attività produttiva."],
 ["Pioggia che dilava il piazzale di deposito dei rottami",2,"È acqua meteorica di dilavamento di superfici esterne."],
 ["Acque di raffreddamento di un processo industriale",1,"Sono reflui dell’attività produttiva."],
 ["Mensa aziendale con scarico separato",0,"Di norma è domestica o assimilata, secondo la disciplina regionale."],
 ["Acqua che scorre sul tetto e sulle aree verdi",2,"È meteorica; di norma non contaminata."],
 ["Spurgo delle torri evaporative",1,"È un refluo di processo."],
 ["Lavaggio dei pavimenti del reparto verniciatura",1,"Contiene residui di lavorazione: industriale."]],
 "Otto reflui di uno stabilimento. Riconosci se sono acque domestiche o assimilate, industriali oppure meteoriche di dilavamento.","Artt. 74 e 101 D.lgs. 152/2006")])
E(C,'M1-Z2','Scarico o rifiuto liquido?',[SC("La vasca dell’autolavaggio interno","Un’impresa di autotrasporti lava i mezzi nel piazzale. Le acque finiscono in una vasca interrata senza uscita, svuotata ogni mese con un’autobotte.",[
 ("Come si qualificano le acque raccolte nella vasca?",[["Scarico in fognatura",False,"Manca il sistema stabile di collettamento verso un corpo recettore."],["Rifiuto liquido, perché sono raccolte e trasportate senza un sistema stabile di collettamento",True,"Corretto: si applica la Parte IV del D.lgs. 152/2006."],["Acque meteoriche",False,"Sono acque di lavaggio di un’attività."]]),
 ("Che cosa comporta la qualificazione come rifiuto?",[["Nessun adempimento",False,"Il rifiuto liquido va gestito come ogni altro rifiuto."],["Codice EER, deposito temporaneo, formulario e verifica dell’autotrasportatore e dell’impianto di destinazione",True,"Corretto: valgono tutte le regole della gestione dei rifiuti."],["Solo un’analisi annuale",False,"Non basta."]]),
 ("L’impresa vuole collegare la vasca alla fognatura. Che cosa serve?",[["Basta aprire un tubo",False,"Sarebbe uno scarico non autorizzato."],["Un’autorizzazione allo scarico, sentito il gestore, con eventuali pretrattamenti come la disoleazione",True,"Corretto: lo scarico di acque reflue industriali in fognatura va autorizzato."],["Una comunicazione all’INAIL",False,"Non è l’ente competente."]])],
 "Senza un sistema stabile di collettamento il refluo è un rifiuto liquido; per trasformarlo in uno scarico servono un collegamento stabile e l’autorizzazione.","Le acque di lavaggio dei mezzi finiscono in una vasca. Qualificale e decidi.","Artt. 74, 124 e 185 D.lgs. 152/2006")])
E(C,'M1-Z3','Autorizzazione allo scarico e valori limite',[LB("Laboratorio · La mappa degli scarichi dello stabilimento","Una PMI metalmeccanica ti chiede di ricostruire la situazione dei suoi scarichi.",[
  ["Attività","lavorazioni meccaniche, sgrassaggio e verniciatura"],["Scarico S1","servizi igienici e mensa → fognatura"],["Scarico S2","acque di sgrassaggio dopo un impianto chimico-fisico → fognatura"],["Scarico S3","acque meteoriche del piazzale di deposito rottami → fosso"],["Titolo","AUA rilasciata nel 2018"]],[
  ("Classifica ciascuno scarico e indica quale titolo serve.",7,"S1: acque reflue domestiche in fognatura, ammesse nel rispetto del regolamento del gestore. S2: acque reflue industriali in fognatura, da autorizzare nell’AUA sentito il gestore. S3: acque meteoriche di dilavamento di superfici contaminate, disciplinate dalla normativa regionale: se rientrano nei casi regionali vanno trattate e autorizzate.",["Ho distinto domestiche, industriali e meteoriche","Ho indicato l’AUA per S2","Ho richiamato la disciplina regionale per S3"]),
  ("Quali valori limite si applicano a S2 e dove si controllano?",7,"Si applicano i limiti della Tabella 3 dell’Allegato 5 alla Parte III, colonna scarico in rete fognaria, o i limiti del gestore se previsti, senza deroghe meno restrittive per le sostanze della Tabella 5. Il controllo avviene nel pozzetto a valle dell’impianto di trattamento e prima della miscelazione con S1.",["Ho indicato la Tabella 3, colonna fognatura","Ho ricordato la Tabella 5","Ho collocato il pozzetto prima della miscelazione"]),
  ("Quali scadenze tieni sotto controllo?",6,"L’AUA dura 15 anni: la domanda di rinnovo va presentata almeno sei mesi prima della scadenza. Vanno inoltre rispettate le frequenze degli autocontrolli e le scadenze di trasmissione dei risultati indicate nell’autorizzazione, e comunicate preventivamente le modifiche.",["Ho indicato la durata di 15 anni","Ho indicato il rinnovo almeno sei mesi prima","Ho previsto autocontrolli e comunicazione delle modifiche"])],
 "In questo laboratorio ricostruisci la mappa degli scarichi di una piccola impresa metalmeccanica. Classifica i tre scarichi, individua i valori limite e il punto di controllo, e definisci le scadenze da presidiare. Poi confronta ogni risposta con la soluzione di riferimento.","D.lgs. 152/2006, artt. 101, 113, 124 · D.P.R. 59/2013")])
E(C,'M1-Z4','Lo scarico in pubblica fognatura',[ES("Esempio guidato · Lo stesso risultato, due recettori","Confronto di un risultato analitico con i limiti della Tabella 3.",[
 ["Il risultato","Il campione medio composito dello scarico ha COD pari a 420 mg/L.","COD 420 mg/L"],
 ["Limite in fognatura","Tabella 3, colonna scarico in rete fognaria: COD ≤ 500 mg/L.","420 ≤ 500 → conforme"],
 ["Limite in acque superficiali","Tabella 3, colonna acque superficiali: COD ≤ 160 mg/L.","420 > 160 → non conforme"],
 ["La conseguenza","Lo stesso refluo è conforme in fognatura ma non potrebbe essere scaricato in un fosso senza trattamento.","Il recettore cambia i limiti"],
 ["Attenzione","Il gestore può fissare limiti diversi per la fognatura, ma non meno restrittivi per le sostanze della Tabella 5.","Leggere sempre l’autorizzazione"]],
 "Un esempio di confronto con i limiti. Il campione ha un COD di quattrocentoventi milligrammi per litro. In fognatura il limite della Tabella tre è cinquecento: lo scarico è conforme. In acque superficiali il limite è centosessanta: non sarebbe conforme. Il corpo recettore cambia i limiti, e il gestore può fissarne di specifici, mai meno restrittivi per le sostanze della Tabella cinque.","Allegato 5 alla Parte III, Tabella 3")])
E(C,'M1-Z5','Autorizzazione, campionamento e divieti',[SC("L’autorizzazione in scadenza","Controllando l’archivio scopri che l’AUA dello stabilimento scade fra quattro mesi e nessuno ha presentato la domanda di rinnovo.",[
 ("Che cosa fai?",[["Presenti subito la domanda, segnalando il ritardo rispetto al termine di sei mesi prima della scadenza",True,"Corretto: la domanda va presentata comunque al più presto, e il ritardo va gestito con l’autorità competente."],["Aspetti la scadenza e poi chiedi una nuova AUA",False,"Alla scadenza lo scarico resterebbe senza titolo."],["Nulla: l’autorizzazione si rinnova da sola",False,"Il rinnovo non è automatico."]]),
 ("Se il titolo scadesse prima del rinnovo, che cosa rischieresti scaricando acque industriali?",[["Nulla, la domanda basta sempre",False,"La continuità dell’esercizio è legata al rispetto dei termini di presentazione."],["La contravvenzione per scarico senza autorizzazione dell’art. 137",True,"Corretto: lo scarico di acque reflue industriali senza titolo è un reato."],["Solo una sanzione del gestore",False,"È una contravvenzione penale."]]),
 ("Come eviti che succeda di nuovo?",[["Uno scadenzario con promemoria a 12 e a 8 mesi dalla scadenza e un responsabile designato",True,"Corretto: la gestione delle scadenze è un controllo organizzativo essenziale."],["Affidarsi alla memoria del titolare",False,"Non è un controllo affidabile."],["Rinnovare ogni anno",False,"Non è necessario né previsto."]])],
 "Rinnovare per tempo, sapere che cosa si rischia, presidiare le scadenze con uno scadenzario: la continuità dello scarico è un risultato organizzativo.","Un’autorizzazione sta per scadere senza domanda di rinnovo. Decidi come intervenire.","D.P.R. 59/2013, art. 5 · art. 137 D.lgs. 152/2006")])
E(C,'M1-Z6','Acque meteoriche di dilavamento e prima pioggia',[LB("Laboratorio · Il piazzale del centro di raccolta","Un centro di raccolta e trattamento di rifiuti metallici ha un piazzale impermeabile esterno.",[
  ["Superficie scolante","2.000 m², pavimentata"],["Attività sul piazzale","deposito di rottami e movimentazione con mezzi"],["Disciplina regionale","acque di prima pioggia: primi 5 mm di precipitazione"],["Situazione","le acque oggi defluiscono in un fosso senza trattamento"]],[
  ("Calcola il volume di prima pioggia da raccogliere a ogni evento.",5,"2.000 m² × 0,005 m = 10 m³. La vasca di prima pioggia deve avere almeno questo volume utile, con un sistema che separi le acque successive.",["Ho convertito 5 mm in 0,005 m","Ho ottenuto 10 m³","Ho previsto la separazione delle acque successive"]),
  ("Quale sistema di trattamento proponi?",7,"Vasca di prima pioggia con svuotamento programmato verso un trattamento di sedimentazione e disoleazione, e scarico nel recettore autorizzato; pulizia periodica e smaltimento dei fanghi e degli oli separati come rifiuti; pozzetto di campionamento a valle.",["Ho previsto sedimentazione e disoleazione","Ho previsto la gestione dei fanghi come rifiuti","Ho previsto il pozzetto di campionamento"]),
  ("Qual è oggi il rischio per l’impresa?",6,"Le acque di dilavamento contaminate scaricate nel fosso senza rispettare la disciplina regionale possono configurare uno scarico non autorizzato, con le relative sanzioni. Serve regolarizzare con l’autorizzazione e, nel frattempo, ridurre il dilavamento coprendo i depositi.",["Ho riconosciuto il rischio di scarico non autorizzato","Ho indicato la regolarizzazione","Ho proposto una misura provvisoria"])],
 "Il laboratorio riguarda un piazzale di duemila metri quadrati dove si depositano rottami. Calcola il volume di prima pioggia, proponi il trattamento e valuta il rischio attuale per l’impresa, poi confronta le tue risposte con la soluzione di riferimento.","Art. 113 D.lgs. 152/2006 · disciplina regionale")])
E(C,'M1-Z7','Esempio applicativo: il pozzetto e l’autocontrollo',[LB("Laboratorio · Leggere un rapporto di prova","Hai ricevuto il rapporto di prova dell’autocontrollo semestrale di uno scarico industriale in fognatura.",[
  ["Campione","medio composito nell’arco di tre ore, pozzetto a valle del trattamento"],["pH","7,8 (limite 5,5–9,5)"],["COD","620 mg/L (limite 500)"],["Solidi sospesi totali","150 mg/L (limite 200)"],["Zinco","1,4 mg/L (limite 1)"]],[
  ("Quali parametri superano i limiti?",5,"COD, 620 contro 500 mg/L, e zinco, 1,4 contro 1 mg/L. pH e solidi sospesi sono conformi.",["Ho individuato COD e zinco","Ho confermato pH e solidi conformi"]),
  ("Le conseguenze dei due superamenti sono uguali?",8,"No. Lo zinco è tra le sostanze della Tabella 5: il superamento è una contravvenzione penale dell’art. 137. Il COD non è nella Tabella 5: il superamento è punito con sanzione amministrativa dell’art. 133. La valutazione tiene conto dell’incertezza di misura secondo i criteri applicabili.",["Ho collegato lo zinco alla Tabella 5 e al reato","Ho collegato il COD alla sanzione amministrativa","Ho considerato l’incertezza di misura"]),
  ("Che cosa fai subito?",7,"Verifico il funzionamento dell’impianto di trattamento, individuo la causa, come un bagno esausto o un dosaggio errato, adotto misure correttive, ripeto il campionamento e, se previsto dall’autorizzazione, comunico il superamento all’autorità e al gestore. Documento tutto.",["Ho previsto la ricerca della causa","Ho previsto azioni correttive e nuovo campionamento","Ho previsto comunicazione e documentazione"])],
 "Leggere un rapporto di prova è un’abilità chiave. Il dossier riporta i risultati di un autocontrollo con quattro parametri. Individua i superamenti, distingui le conseguenze e decidi le azioni immediate, poi confronta le tue risposte con la soluzione di riferimento.","Allegato 5 alla Parte III · artt. 133 e 137 D.lgs. 152/2006")])
E(C,'M1-Z8','Gli impianti di trattamento dei reflui industriali',[CL("Quale trattamento?","Seleziona un inquinante, poi il trattamento più adatto.",["Chimico-fisico","Biologico","Separazione fisica"],[
 ["Metalli disciolti da galvanica",0,"Precipitazione chimica, coagulazione e flocculazione."],["Sostanza organica biodegradabile di un’industria alimentare",1,"Fanghi attivi per abbattere BOD₅ e COD biodegradabile."],
 ["Oli e idrocarburi liberi",2,"Disoleatore a gravità o a coalescenza."],["pH acido da decapaggio",0,"Neutralizzazione."],
 ["Sabbie e solidi grossolani",2,"Grigliatura e dissabbiatura."],["Reflui zootecnici diluiti",1,"Trattamento biologico."]],
 "Sei inquinanti. Scegli il trattamento più adatto per ciascuno.","BAT Reference Documents · art. 101 D.lgs. 152/2006"),
 SC("Il depuratore biologico in sofferenza","Il depuratore a fanghi attivi di un caseificio produce da una settimana un effluente torbido e il COD in uscita è salito.",[
  ("Che cosa controlli per primo?",[["Il carico in ingresso e l’ossigeno disciolto nella vasca di ossidazione",True,"Corretto: sovraccarichi organici e carenza di ossigeno sono le cause più frequenti."],["Il colore delle pareti del locale",False,"Non incide."],["Nulla: si sistema da solo",False,"Il rischio è il superamento dei limiti."]]),
  ("Scopri che il siero di latte viene scaricato nel depuratore. Che cosa fai?",[["Lo separi e lo gestisci come sottoprodotto o rifiuto, perché è un carico organico molto elevato",True,"Corretto: il siero ha un carico organico altissimo e manda in sovraccarico l’impianto."],["Aumenti la diluizione con acqua di rete",False,"La diluizione per rispettare i limiti è vietata."],["Lo lasci, il depuratore si adatterà",False,"Il sovraccarico continuerebbe."]]),
  ("Il COD in uscita supera il limite. Che cosa fai?",[["Misure correttive, campionamento di verifica e comunicazioni previste dall’autorizzazione",True,"Corretto: documentare e comunicare tutela l’impresa."],["Nulla fino al prossimo autocontrollo",False,"Il superamento va gestito subito."],["Chiudi il pozzetto di campionamento",False,"Impedire il controllo è vietato."]])],
  "Controllare carico e ossigeno, eliminare i carichi impropri senza diluire, gestire il superamento con trasparenza: è la gestione corretta di un depuratore in difficoltà.","Un depuratore biologico peggiora. Trova la causa e intervieni.","Art. 101, c. 5, D.lgs. 152/2006")])
E(C,'M1-Z9','Illeciti amministrativi e reati negli scarichi',[LB("Laboratorio · Il verbale dell’ARPA","Dopo un sopralluogo ricevi un verbale con tre rilievi.",[
  ["Rilievo 1","superamento del limite dei solidi sospesi totali nello scarico in fognatura"],["Rilievo 2","pozzetto di campionamento coperto da materiali e non accessibile"],["Rilievo 3","scarico S4 di acque di lavaggio non indicato nell’AUA"]],[
  ("Qualifica ciascun rilievo: illecito amministrativo o contravvenzione?",7,"Rilievo 1: superamento per un parametro non compreso nella Tabella 5, sanzione amministrativa dell’art. 133. Rilievo 2: rendere inaccessibile il punto di campionamento viola le prescrizioni e l’obbligo di accessibilità; secondo il caso può rilevare come inosservanza delle prescrizioni o impedimento del controllo. Rilievo 3: scarico di acque reflue industriali senza autorizzazione, contravvenzione dell’art. 137.",["Ho qualificato il rilievo 1 come amministrativo","Ho qualificato il rilievo 3 come contravvenzione","Ho valutato il rilievo 2 con cautela"]),
  ("Per le contravvenzioni, quale strada può portare all’estinzione?",6,"La procedura estintiva della Parte VI-bis: l’organo di vigilanza impartisce una prescrizione con un termine; se l’adempimento è verificato, il contravventore paga un quarto del massimo dell’ammenda entro trenta giorni e il reato si estingue. Si applica se non c’è danno o pericolo concreto e attuale.",["Ho descritto la prescrizione e la verifica","Ho indicato il pagamento di un quarto del massimo","Ho indicato la condizione dell’assenza di danno"]),
  ("Quale piano di azioni proponi all’impresa?",7,"Liberare e segnalare il pozzetto subito; sospendere o convogliare lo scarico S4 e chiedere la modifica dell’AUA; ricercare la causa dei solidi sospesi e migliorare il trattamento; ripetere i campionamenti; aggiornare procedure e formazione; documentare tutto per l’organo di controllo.",["Ho previsto azioni immediate","Ho previsto la modifica dell’AUA","Ho previsto verifiche e documentazione"])],
 "Il laboratorio parte da un verbale dell’ARPA con tre rilievi. Qualifica ciascun rilievo, individua la strada per estinguere le contravvenzioni e proponi un piano di azioni, poi confronta le tue risposte con la soluzione di riferimento.","Artt. 101, 133, 137 e Parte VI-bis D.lgs. 152/2006"),
 CL("Illecito amministrativo o contravvenzione?","Seleziona una violazione, poi la categoria.",["Illecito amministrativo","Contravvenzione"],[
  ["Scarico di acque reflue industriali senza autorizzazione",1,"Art. 137, comma 1."],["Superamento del limite del COD",0,"Parametro non in Tabella 5: art. 133."],
  ["Superamento del limite del cadmio",1,"Sostanza della Tabella 5: art. 137."],["Superamento del limite dei solidi sospesi",0,"Art. 133."],
  ["Scarico industriale con sostanze pericolose senza autorizzazione",1,"Fattispecie aggravata dell’art. 137."],["Scarico di acque domestiche senza autorizzazione fuori fognatura",0,"Sanzione amministrativa dell’art. 133."]],
  "Sei violazioni in materia di scarichi. Distingui gli illeciti amministrativi dalle contravvenzioni.","Artt. 133 e 137 D.lgs. 152/2006")])
E(C,'M1-Z10','Prelievi idrici e riutilizzo delle acque reflue',[LB("Laboratorio · Il bilancio idrico dello stabilimento","Uno stabilimento vuole ridurre prelievi e scarichi.",[
  ["Prelievo da pozzo","12.000 m³ l’anno, con concessione"],["Scarico in fognatura","9.500 m³ l’anno"],["Usi principali","raffreddamento 6.000 m³, lavaggi 4.000 m³, servizi 2.000 m³"],["Depuratore interno","effluente conforme, oggi tutto scaricato"]],[
  ("Quanta acqua non finisce allo scarico e perché?",5,"12.000 − 9.500 = 2.500 m³ l’anno, circa il 21% del prelievo: evaporazione nel raffreddamento, acqua nei prodotti e perdite. Il bilancio va verificato con i misuratori.",["Ho calcolato 2.500 m³","Ho indicato le cause probabili","Ho previsto la verifica con misuratori"]),
  ("Proponi due interventi di riduzione e stimane l’effetto.",8,"Ricircolo a circuito chiuso del raffreddamento: se riduce del 70% il consumo, si risparmiano circa 4.200 m³. Riutilizzo nei lavaggi dell’effluente depurato, se la qualità lo consente: fino a 4.000 m³. Insieme possono più che dimezzare il prelievo.",["Ho proposto il ricircolo del raffreddamento","Ho proposto il riutilizzo interno dell’effluente","Ho stimato i volumi risparmiati"]),
  ("Quali aspetti autorizzativi devi considerare?",5,"Comunicare o chiedere la modifica dell’AUA per la variazione dello scarico; aggiornare la concessione di derivazione se cambiano i volumi; verificare la qualità dell’acqua riutilizzata rispetto all’uso; continuare a misurare prelievi e scarichi.",["Ho previsto la modifica dell’AUA","Ho considerato la concessione","Ho previsto il controllo della qualità"])],
 "Nel laboratorio costruisci il bilancio idrico di uno stabilimento. Calcola l’acqua che non arriva allo scarico, proponi due interventi di riduzione con una stima dei volumi e individua gli aspetti autorizzativi, poi confronta le tue risposte con la soluzione di riferimento.","R.D. 1775/1933 · D.M. 185/2003 · D.P.R. 59/2013"),
 AP("Gli scarichi della tua azienda","Verifica la situazione degli scarichi della tua organizzazione.",["Ho l’elenco aggiornato degli scarichi","Gli scarichi sono tutti autorizzati","Conosco la scadenza del titolo","Il pozzetto è accessibile e identificato","Gli autocontrolli sono pianificati","Le acque meteoriche sono gestite secondo la disciplina regionale","I prelievi idrici sono misurati"],"La lacuna più importante e come la colmeresti","Es.: scadenza dell’AUA non presidiata → scadenzario con promemoria a 12 mesi",
  "Verifica la situazione degli scarichi della tua azienda e indica la lacuna più importante e come colmarla.",3)])
E(C,'M1-Z11','Sanzioni per gli scarichi',[VF("Ripasso · Scarichi e controlli",[["Il campione medio composito è di norma prelevato nell’arco di tre ore.",True,"Vero: è il riferimento dell’Allegato 5 alla Parte III, salvo diversa prescrizione."],["Si possono rispettare i limiti diluendo lo scarico con acqua di pozzo.",False,"Falso: la diluizione con acque prelevate allo scopo è vietata."],["Il pozzetto di campionamento deve essere accessibile all’autorità di controllo.",True,"Vero: art. 101, comma 3."],["Le acque raccolte in una vasca e portate via con autobotte sono uno scarico.",False,"Falso: sono rifiuti liquidi."]],"Ripasso: quattro affermazioni su scarichi e controlli.","D.lgs. 152/2006, Parte III")])
